export function translate(locale: Locale, key: string, params: Params = {}) {
  const dictionary = locale === 'ru' ? ru : en
  const generatedSquad = /^squad\.generated\.(\d+)$/.exec(key)
  const template = dictionary[key] ?? (generatedSquad
    ? locale === 'ru' ? `Отряд ${generatedSquad[1]}` : `Squad ${generatedSquad[1]}`
    : key)
  return template.replace(/\{(\w+)\}/g, (_, name: string) => {
    const value = params[name]
    if (value === undefined) return `{${name}}`
    return typeof value === 'string' ? dictionary[value] ?? value : String(value)
  })
}

export function squadDisplayName(locale: Locale, squad: Pick<Squad, 'name' | 'customName'>) {
  const name = squad.customName ?? squad.name
  return /^squad\.(?:alpha|bravo|charlie|delta|echo|foxtrot|generated\.\d+)$/.test(name)
    ? translate(locale, name)
    : name
}
